-- Preview gate + cue fix for the dev QB-pack lesson.
-- Generated by scripts/dev_ingest_qb_pack.py. Forward-only migration applied on
-- top of 20260530000000_dev_test_qb_program_lesson.sql.
--
-- 1) Adds lessons.production_ready (default TRUE so every existing lesson is
--    unchanged and stays visible to all users).
-- 2) Updates the dev lesson's content_blocks to the reviewed, sentence-level
--    cues and marks it production_ready = false.
-- 3) Tags it 'mindfulness' so it renders with the correct MAC color + trophy
--    tag and appears in that library tab exactly as it would in production.
--
-- The lessons Edge Function shows production_ready = false lessons ONLY to
-- is_dev accounts, in both the catalog list and the player. Real production
-- users see no change until production_ready is flipped to true.

begin;

alter table public.lessons
  add column if not exists production_ready boolean not null default true;

comment on column public.lessons.production_ready is
  'When false, the lesson is a not-yet-live preview: the lessons Edge Function serves it only to is_dev accounts (list + detail). Flip to true to release it to all users. Defaults true so existing content is unaffected.';

update public.lessons set
  content_blocks = '{"blocks":[{"type":"voiceover","audio_files":["grant-chiasson/qb-program/lesson_01/seg_01.mp3"],"total_audio_seconds":87.28,"timed_text":[{"start_s":0.0,"text":"Day 15. Your focus anchor — the word your mind returns to when it drifts."},{"start_s":9.34,"text":"The most powerful anchor isn''t just a word in your head — it''s physical."},{"start_s":22.7,"text":"Elite athletes do this instinctively. They''re trained focus triggers."},{"start_s":47.86,"text":"The key is consistency — the same thing, the same way, every single time."},{"start_s":57.26,"text":"Do it enough times in a focused state and it begins to trigger the state."},{"start_s":66.68,"text":"That''s what we''re building today."},{"start_s":69.08,"text":"Think about the physical environment where you compete."},{"start_s":72.46,"text":"What is something you can see, touch, feel or do?"},{"start_s":77.12,"text":"Something always available in that space — that''s your competition anchor."},{"start_s":83.52,"text":"On your screen, you''re going to identify it and lock it in."}]},{"type":"flash_cards","cards":[{"front":"Flash Card 1: \"Think about the physical space where you compete. What do you see, hear, or feel in that environment that is always there — every competition, every time?\"","back":"Text Entry 1: Athlete describes their competition environment. Saved to journal."},{"front":"Flash Card 2: \"Identify your physical anchor — something in that space, or something you wear or carry, that you can use as a consistent focus trigger. Something you can touch, see, or do deliberately before or during competition.\"","back":"Text Entry 2: Athlete names and describes their physical anchor. Saved to profile."}],"ambient_audio":"ambient/ambient_music.mp3"},{"type":"voiceover","audio_files":["grant-chiasson/qb-program/lesson_01/seg_02.mp3"],"total_audio_seconds":20.14,"timed_text":[{"start_s":0.0,"text":"Every rep with that anchor strengthens the link to your focused state."},{"start_s":6.62,"text":"Do it in practice, do it in warmups, do it in competition."},{"start_s":11.12,"text":"The more consistent you are, the faster it works when the pressure is real."},{"start_s":16.26,"text":"Check out the journal and have to finish."},{"start_s":17.96,"text":"Day 15 is complete."}]},{"type":"journal_prompt","prompt":"What physical anchor did you choose — and why does that specific thing feel right for your competition environment?"}]}'::jsonb,
  duration_seconds = 197,
  production_ready = false,
  updated_at = now()
where id = 'dddddddd-dddd-dddd-dddd-dddddddddddd';

insert into public.lesson_categories (lesson_id, category)
values ('dddddddd-dddd-dddd-dddd-dddddddddddd', 'mindfulness')
on conflict (lesson_id, category) do nothing;

commit;
